function calendarDay(value){const d=new Date(value);return new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())}function latestByFid(table){const rows=table?Array.from(table,r=>r.toJSON?r.toJSON():r):[];return new Map(rows.map(r=>[r.fid,{...r,date:calendarDay(r.date)}]))}function latestFor(row,latest){const quote=latest?.get(row.fid);if(!quote||!row.data_month)return null;const[year,month]=row.data_month.split("-").map(Number);return quote.date>new Date(year,month,0)?quote:null}export{latestByFid,latestFor};
